 private boolean trustedPage(String url){return url!=null&&(url.equals(HOME)||url.equals(MIGRATION));}
 private WebResourceResponse localAsset(Uri uri){
  try{
   if(!trustedOrigin(uri)||!uri.getPath().startsWith("/assets/"))return denied();
   String path=uri.getPath().substring(8);if(path.isEmpty()||path.contains("..")||path.startsWith("/"))return denied();
   String ext=path.contains(".")?path.substring(path.lastIndexOf('.')+1):"";
   String mime=MimeTypeMap.getSingleton().getMimeTypeFromExtension(ext);
   if(ext.equals("js")||ext.equals("mjs"))mime="text/javascript";if(ext.equals("wasm"))mime="application/wasm";if(mime==null)mime="application/octet-stream";
   Map<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-cache");headers.put("X-Content-Type-Options","nosniff");headers.put("Permissions-Policy","camera=(), microphone=()");
   return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,getAssets().open(path));
  }catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}
 }
 private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}
