  prayerLocationListener=new android.location.LocationListener(){public void onLocationChanged(android.location.Location l){if(prayerLocationListener!=this||l==null)return;if(prayerBestLocation==null||l.getAccuracy()<prayerBestLocation.getAccuracy())prayerBestLocation=l;if(l.hasAccuracy()&&l.getAccuracy()<=10000)prayerLocationResult(l,"");}public void onStatusChanged(String p,int status,Bundle extras){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};
  boolean requested=false;for(String provider:new String[]{android.location.LocationManager.NETWORK_PROVIDER,android.location.LocationManager.GPS_PROVIDER})if(manager.isProviderEnabled(provider)){try{manager.requestLocationUpdates(provider,1000,0,prayerLocationListener);requested=true;}catch(Exception ignored){}}
  if(!requested){prayerLocationResult(null,"خدمة الموقع متوقفة؛ فعّلها أو اختر مدينتك يدويًا");return;}
  prayerHandler.postDelayed(()->prayerLocationResult(prayerBestLocation,"تعذر تحديد الموقع الآن؛ يمكنك اختيار المدينة يدويًا"),40000);
