 @JavascriptInterface public void fajrDial(String raw){final String number=FajrCompanion.number(raw);runOnUiThread(()->{if(fajrCall!=null){fajrCall.cancel();fajrCall=null;}
  if(number==null){fajrJs("onFajrCall","{\"state\":\"failed\",\"reason\":\"number\"}");return;}
  if(checkSelfPermission(Manifest.permission.CALL_PHONE)!=PackageManager.PERMISSION_GRANTED){fajrJs("onFajrCall","{\"state\":\"failed\",\"reason\":\"permission\"}");return;}
  final FajrCallTracker[] self=new FajrCallTracker[1];
  self[0]=new FajrCallTracker(this,json->{if(fajrCall!=self[0])return;String st=json.optString("state");if(!"started".equals(st))fajrCall=null;fajrJs("onFajrCall",json.toString());});
  fajrCall=self[0];boolean tracked=fajrCall.start();
  try{startActivity(new Intent(Intent.ACTION_CALL,Uri.parse("tel:"+Uri.encode(number))));}catch(Exception e){if(fajrCall!=null){FajrCallTracker t=fajrCall;fajrCall=null;t.cancel();}fajrJs("onFajrCall","{\"state\":\"failed\",\"reason\":\"dial\"}");return;}
  if(!tracked){fajrCall=null;fajrJs("onFajrCall","{\"state\":\"started\"}");}});}
